window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-26501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενεχάρμης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 922 na letra μ · nº geral 26501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = μενέχαρμος.</p></section></article>\n<article id=\"entry-dgp-26502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενέχαρμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 923 na letra μ · nº geral 26502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que espera o combate com firmeza; valoroso. 〈μένω, χάρμη〉</p></section></article>\n<article id=\"entry-dgp-26503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενέω</h1><div class=\"entry-meta\"><span>DGP · ordem 924 na letra μ · nº geral 26503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. jôn. de μένω.</p></section></article>\n<article id=\"entry-dgp-26504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μένῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 925 na letra μ · nº geral 26504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. ép. pres. subj. de μένω.</p></section></article>\n<article id=\"entry-dgp-26505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 926 na letra μ · nº geral 26505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de μένω.</p></section></article>\n<article id=\"entry-dgp-26506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μενίππειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 927 na letra μ · nº geral 26506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Menipo; menipeu. 〈Μένιππος〉</p></section></article>\n<article id=\"entry-dgp-26507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μένιππος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 928 na letra μ · nº geral 26507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Menipo, n. de homem.</p></section></article>\n<article id=\"entry-dgp-26508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοεικής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 929 na letra μ · nº geral 26508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que agrada ao espírito; que alegra o coração; agradável 2 conveniente; como tem de ser; bom. 〈μένος, εἴκω〉</p></section></article>\n<article id=\"entry-dgp-26509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοινάᾳ</h1><div class=\"entry-meta\"><span>DGP · ordem 930 na letra μ · nº geral 26509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres. ind. ép. de μενοινάω.</p></section></article>\n<article id=\"entry-dgp-26510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοινάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 931 na letra μ · nº geral 26510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐμενοίνων, aor. ἐμενοίνησα, fut. e perf. desus.) 1 sonhar com; pensar em; projetar algo, ac. ou inf. 2 maquinar; tramar algo, ac., contra alguém, dat. 3 desejar vivamente; aspirar a, dat. 〈μένος〉</p></section></article>\n<article id=\"entry-dgp-26511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοίνεον</h1><div class=\"entry-meta\"><span>DGP · ordem 932 na letra μ · nº geral 26511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. jôn. de μενοινέω.</p></section></article>\n<article id=\"entry-dgp-26512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 933 na letra μ · nº geral 26512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = μενοινάω.</p></section></article>\n<article id=\"entry-dgp-26513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοινήῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 934 na letra μ · nº geral 26513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. pres. ind. ép. de μενοινάω.</p></section></article>\n<article id=\"entry-dgp-26514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μενοινώω</h1><div class=\"entry-meta\"><span>DGP · ordem 935 na letra μ · nº geral 26514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = μενοινάω.</p></section></article>\n<article id=\"entry-dgp-26515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μενοιτιάδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 936 na letra μ · nº geral 26515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o filho de Menécio, Pátroclo. 〈Με­νοίτιος〉</p></section></article>\n<article id=\"entry-dgp-26516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μενοίτιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 937 na letra μ · nº geral 26516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Menécio, pai de Pátroclo.</p></section></article>\n<article id=\"entry-dgp-26517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μένος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 938 na letra μ · nº geral 26517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 princípio vital; alma: μένος Ἕκτορος hom. a alma de Heitor, i.e., Heitor 2 alma como princípio de força física; força; vigor; potência: μένος Ἀτρεΐδαο hom. a força do Atrida, i.e., o possante Atrida 3 alma; princípio de vontade; força de ânimo; coragem 4 alma como fonte de paixões; coração; espírito; ardor; paixão 5 cólera 6 violência: τὸ τοῦ θυμοῦ μένος ar. a violência do ímpeto.</p></section></article>\n<article id=\"entry-dgp-26518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεντἄν</h1><div class=\"entry-meta\"><span>DGP · ordem 939 na letra μ · nº geral 26518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase át. de μέντοι ἄν.</p></section></article>\n<article id=\"entry-dgp-26519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέντοι</h1><div class=\"entry-meta\"><span>DGP · ordem 940 na letra μ · nº geral 26519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μέν.</p></section></article>\n<article id=\"entry-dgp-26520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεντορουργής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 941 na letra μ · nº geral 26520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito por Mentor. 〈Μέντωρ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-26521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μέντωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 942 na letra μ · nº geral 26521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Mentor, n. de homem.</p></section></article>\n<article id=\"entry-dgp-26522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μένω</h1><div class=\"entry-meta\"><span>DGP · ordem 943 na letra μ · nº geral 26522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μενῶ, aor. ἔμεινα, perf. μεμένηκα) 1 esperar alguém ou algo, ac.; esperar para, inf.: μένω δ’ ἀκοῦσαι ésql. fico para escutar, μένειν εἰσόκεν com subj. esperar que 2 aguardar: θεῶν ἀρὰ μένει σε sóf. a maldição dos deuses te aguarda 3 esperar de pé firme, ac. ♦ intr. 4 estar ou manter-se fixo, estável, sedentário: μένει ἡ στήλη hom. (como) a coluna mantém-se fixa, μ. δόμοις ou ἐν δόμοις sóf., εἴσω δόμων ésql., κατ’ οἶκον eur. ficar dentro de casa, μ. κατὰ χώραν tuc. permanecer no local em seu posto 5 ser constante em; persistir em, ἐν e dat.: μ. ἐν τῷ ἐπιτηδεύματι plat. persistir no empenho, μ. ἐπὶ τῷ βίῳ plat. persistir no seu gênero de vida 6 permanecer; resistir; durar: ὁ νομος μένει eur. a lei permanece 7 ficar de pé firme; resistir: οὐ μένειν sóf. ceder 8 ficar para trás: οἱ μένοντες xen. os retardatários 9 permanecer; habitar.</p></section></article>\n<article id=\"entry-dgp-26523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 944 na letra μ · nº geral 26523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μεριῶ, aor. ἐμέρισα, perf. μεμέρικα; pas. fut. μερισθήσομαι, aor. ἐμερίσθην, perf. μεμέρισμαι) 1 repartir; dividir; fracionar ♦ méd. (fut. μερίσομαι e με­ριοῦμαι, aor. ἐμερισάμην) 2 dividir algo, ac., com alguém, μετά e gen. 3 repartir; distribuir; partilhar algo, ac., com alguém, πρός e ac. 4 atribuir para si: μ. κακίαν sept. herdar a perversidade 5 ter parte em; participar de algo, gen.: μ. ἀδικήματος artt. ter parte na injustiça ♦ pas. 6 bíbl. tornar-se dissidente. 〈μερίς〉</p></section></article>\n<article id=\"entry-dgp-26524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέριμνα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 945 na letra μ · nº geral 26524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. 1 cuidado; preocupação; solicitude 2 disposição; espírito; pensamento.</p></section></article>\n<article id=\"entry-dgp-26525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεριμνάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 946 na letra μ · nº geral 26525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐμερίμνησα, perf. μεμερίμνηκα; aor. pas. ἐμεριμνήθην, perf. μεμερίμνημαι) 1 estar inquieto, desassossegado, preocupado com, ac. 2 inquietar-se com; buscar saber com inquietude algo, ac., a respeito de algo, περί e gen. 〈μέριμνα〉</p></section></article>\n<article id=\"entry-dgp-26526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερίμνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 947 na letra μ · nº geral 26526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cuidado; preocupação; inquietude. 〈μεριμνάω〉</p></section></article>\n<article id=\"entry-dgp-26527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 948 na letra μ · nº geral 26527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedaço; parte, gen.: μ. τῆς οὐσίας men. parte dos bens 2 ração de alimento; porção 3 cota; cota parte; escote 4 bíbl. lote de terreno; gleba 5 bíbl. distrito; província 6 classe social 7 partido político; facção 8 contribuição; ajuda; influência: ὁ καιρὸς ἐν πᾶσι μεγάλην ἔχει μέριδα pol. o momento oportuno exerce, em tudo, grande influência. 〈μέρος〉</p></section></article>\n<article id=\"entry-dgp-26528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 949 na letra μ · nº geral 26528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de dividir; divisão. 〈μερίζω〉</p></section></article>\n<article id=\"entry-dgp-26529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεριστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 950 na letra μ · nº geral 26529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. quem faz a partilha; quem distribui; distribuidor. 〈μερίζω〉</p></section></article>\n<article id=\"entry-dgp-26530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μερμερίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 951 na letra μ · nº geral 26530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o filho de Mérmero, Ilo.</p></section></article>\n<article id=\"entry-dgp-26531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερμέριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 952 na letra μ · nº geral 26531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μέρμερος.</p></section></article>\n<article id=\"entry-dgp-26532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέρμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 953 na letra μ · nº geral 26532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que causa preocupação; triste; penoso; terrível; funesto 2 que medita; que calcula; astuto (pessoa) 3 de natureza difícil; fastidioso (pessoa) ♦ τὰ μέρμερα 4 façanhas terríveis.</p></section></article>\n<article id=\"entry-dgp-26533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μέρμερος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 954 na letra μ · nº geral 26533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Mérmero, n. de um troiano e de um dos filhos de Medéia.</p></section></article>\n<article id=\"entry-dgp-26534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέρμηρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 955 na letra μ · nº geral 26534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preocupação; inquietude.</p></section></article>\n<article id=\"entry-dgp-26535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερμηρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 956 na letra μ · nº geral 26535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μερμηρίξω, aor. ἐμερμήρισα, ép. μερμή­ριξα) 1 estar aflito, inquieto; inquietar-se com alguém, περί e gen.; μερμ. δίχα ou διάνδιχα hom. estar incerto, dividido em suas decisões 2 inquietar-se em, inf. 3 perguntar-se com ansiedade algo, or.: ἐμερμήριζε ᾧ τρόπῳ προσαγάγοι πρὸς τὸ τεῖχος luc. perguntava-se ansioso de que modo subiria no muro 4 meditar; maquinar algo, ac., contra alguém, dat. 〈μέρμηρα〉</p></section></article>\n<article id=\"entry-dgp-26536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέρμις, ιθος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 957 na letra μ · nº geral 26536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fio; cordão.</p></section></article>\n<article id=\"entry-dgp-26537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μερμνός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 958 na letra μ · nº geral 26537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de falcão.</p></section></article>\n<article id=\"entry-dgp-26538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μέροπες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 959 na letra μ · nº geral 26538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Méropes, antigos habitantes da ilha de Cós.</p></section></article>\n<article id=\"entry-dgp-26539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεροπίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 960 na letra μ · nº geral 26539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a terra dos méropes, i.e., a ilha de Cós. 〈Μέροπες〉</p></section></article>\n<article id=\"entry-dgp-26540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέρος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 961 na letra μ · nº geral 26540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedaço; parte; porção; quota; fração: τὰ τοῦ σώματος μέρη plat. as partes do corpo, em parte, μέρος τι tuc., ἐπὶ μέρους luc., ἐκ μέρους n.t., ἀπὸ μέρους, κατὰ μέρος, κατὰ μέρη plat. ou ἀπὸ μέρους tuc. em parte, parcialmente, μέγα μέρος plat. em grande parte 2 no pl., com num., fração: τὰ δύο μέρη duas frações de um conjunto de três, i.e., dois terços, τὰ τρία μέρη três quartos 3 elemento ou parte de um grupo, de uma população: φασὶ δὴ τὸ τῶν Ἰνδῶν πλῆθος ἐς ἑπτὰ μέρη διωρίσθαι estr. diz-se que a população da Índia se divide em sete elementos 4 Mil. recruta: ἐν τοῖς μέρεσι ésqn. entre os os recrutas 5 parte dos sufrágios, ger. o quinto necessário para uma eleição 6 porção atribuída pelo destino; sorte: κοινοῦ θανάτου μέρος sóf. o destino de morrerem juntos 7 função; cargo; papel: τὸ ἐμὸν μέρος sóf. de minha parte, no que me compete, ὅσον τὸ σὸν μέρος ou τὸ σὸν μέρος sóf. tanto quanto te concerne, tua parte, ἐν οὐδενὸς εἶναι μέρει dem. ser tido como nada 8 parte de uma seqüência de eventos; turno: ἐπεί τε αὐτῆς μέρος ἐγένετο τῆς ἀπίξιος παρὰ τὸν μάγον her. quando chegou sua vez de ir dormir com o mago, ἐν μέρει, ἐν τῷ μέρει, κατὰ μέρος, ἀνὰ μέρος em seu turno, turno a turno, ἐγὼ δ’ ἐν τῷ μέρει xen. por mim, de minha parte 9 consideração; conta; estima: ἐν μέρει τινὸς ποιεῖσθαι ou τιθέναι τι ou τινά considerar alguém ou algo como parte de algo, ἐν ἀρετῆς καὶ σοφίας τιθεῖς μέρει τὴν ἀδικίαν plat. estejas tomando a injustiça como virtude e sabedoria 10 ação; resolução: πολλὴν αὐτοῖς παρεῖχεν τοῦτο τὸ μέρος δυσχέρειαν pol. essa resolução causou-lhes muitos transtornos.</p></section></article>\n<article id=\"entry-dgp-26541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέροψ, οπος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 962 na letra μ · nº geral 26541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ger. pl. os mortais; os homens 2 melharuco; abelheiro, pássaro.</p></section></article>\n<article id=\"entry-dgp-26542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσάγκυλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 963 na letra μ · nº geral 26542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mesângulo, arma de arremeço dotada de uma correia colocada ao meio. 〈μέσος, ἀγκύλη〉</p></section></article>\n<article id=\"entry-dgp-26543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 964 na letra μ · nº geral 26543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar entre, no meio 2 (sofrimento, noite) estar na metade, op. a ἄρχω e a λήγω 3 colocar no meio; interpor.</p></section></article>\n<article id=\"entry-dgp-26544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσαιπόλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 965 na letra μ · nº geral 26544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">meio branco; grisalho. 〈μέσος, πολιός〉</p></section></article>\n<article id=\"entry-dgp-26545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσαίτατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 966 na letra μ · nº geral 26545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de μέσος.</p></section></article>\n<article id=\"entry-dgp-26546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσαίτερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 967 na letra μ · nº geral 26546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. de μέσος.</p></section></article>\n<article id=\"entry-dgp-26547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσακτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 968 na letra μ · nº geral 26547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">situado entre duas margens. 〈μέσος, ἀκτή1〉</p></section></article>\n<article id=\"entry-dgp-26548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσαμβρίη, Μεσαμβρίη</h1><div class=\"entry-meta\"><span>DGP · ordem 969 na letra μ · nº geral 26548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = μεσημβρία, Μεσημβρία.</p></section></article>\n<article id=\"entry-dgp-26549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσατος</h1><div class=\"entry-meta\"><span>DGP · ordem 970 na letra μ · nº geral 26549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. poét. de μέσος.</p></section></article>\n<article id=\"entry-dgp-26550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσαυλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 971 na letra μ · nº geral 26550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. μέσαυλος.</p></section></article>\n<article id=\"entry-dgp-26551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσαυλος,</h1><div class=\"entry-meta\"><span>DGP · ordem 972 na letra μ · nº geral 26551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. μέσσαυλος, át. μέταυλος, ος, ον 1 situado no pátio interno: μέταυλος θύρα lís. porta do pátio interno que dá acesso aos aposentos da casa ♦ ὁ μέσαυλος e τὸ μέσαυλον 2 pátio interno onde se encontram portas que davam acesso ao aposento dos homens e ao das mulheres 3 habitação 4 estábulo no pátio interno 5 covil de animal selvagem; antro. 〈μέσος, αὐλή〉</p></section></article>\n<article id=\"entry-dgp-26552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσδων</h1><div class=\"entry-meta\"><span>DGP · ordem 973 na letra μ · nº geral 26552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = μέζων, μείζων.</p></section></article>\n<article id=\"entry-dgp-26553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσεγγυάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 974 na letra μ · nº geral 26553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar como garantia ♦ méd. 2 exigir fiança; exigir garantia. 〈μεσέγγυος〉</p></section></article>\n<article id=\"entry-dgp-26554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσεγγύημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 975 na letra μ · nº geral 26554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fiança depositada nas mãos de um terceiro. 〈μεσεγγυάω〉</p></section></article>\n<article id=\"entry-dgp-26555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσέγγυος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 976 na letra μ · nº geral 26555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">depositário. 〈μέσος, ἐγγύη〉</p></section></article>\n<article id=\"entry-dgp-26556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσεγγύωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 977 na letra μ · nº geral 26556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μεσεγγύημα.</p></section></article>\n<article id=\"entry-dgp-26557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 978 na letra μ · nº geral 26557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar no meio de ou entre, gen.: ἐν μεσεύσᾳ ᾠδᾷ dór. a.p. na metade do canto, [μοναρχικῆς καὶ δημοκρατικῆς πολιτείας] ἀεὶ δεῖ μεσεύειν τὴν πολιτείαν plat. a constituição deve ser sempre um meio-termo entre democrática e monárquica 2 manter-se neutro. 〈μέσος〉</p></section></article>\n<article id=\"entry-dgp-26558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσηγύ</h1><div class=\"entry-meta\"><span>DGP · ordem 979 na letra μ · nº geral 26558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μεσηγύς, ép. μεσσηγύ e μεσσηγύς adv. 1 (lugar) no meio de, gen. ou dat. 2 (tempo) no intervalo; durante o intervalo entretanto; τὸ μ. durante o intervalo de tempo 3 a meio-termo entre dois extremos. 〈μέσος〉</p></section></article>\n<article id=\"entry-dgp-26559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 980 na letra μ · nº geral 26559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colocado ao meio. 〈μέσος〉</p></section></article>\n<article id=\"entry-dgp-26560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσημβρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 981 na letra μ · nº geral 26560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o meio do dia; meio-dia: ἐν μεσημ­βρίᾳ, ἅμα μεσημβρίᾳ xen. ao meio-dia 2 o meridiano; o sul: τὰ κατὰ μεσημβρίαν fílon as regiões meridionais. 〈μέσος, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-26561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσημβρινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 982 na letra μ · nº geral 26561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do meio do dia; de meio-dia: μεσ. ᾠδός a.p. a cantora do meio-dia, i.e., a cigarra 2 situado ao sul; do sul; meridional: ὁ μεσ. κύκλος plut. o meridiano ♦ ὁ μεσημβρινός 3 o meridiano ♦ τὰ μεσημβρινά 4 regiões meridionais. 〈μεσημβρία〉</p></section></article>\n<article id=\"entry-dgp-26562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεσήνη</h1><div class=\"entry-meta\"><span>DGP · ordem 983 na letra μ · nº geral 26562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μεσσήνη, ης (ἡ) 1 Messênia, região do Pelo­poneso 2 Messena, capital da Messênia 3 Messena, atual Messina, cidade da Sicília.</p></section></article>\n<article id=\"entry-dgp-26563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεσήνιος</h1><div class=\"entry-meta\"><span>DGP · ordem 984 na letra μ · nº geral 26563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Μεσσήνιος, α, ον de Messena ou da Mes­sênia. 〈Μεσήνη〉</p></section></article>\n<article id=\"entry-dgp-26564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσήρης,</h1><div class=\"entry-meta\"><span>DGP · ordem 985 na letra μ · nº geral 26564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. μεσσήρης, ης, ες ajustado no meio; colocado ao meio. 〈μέσος〉</p></section></article>\n<article id=\"entry-dgp-26565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσιτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 986 na letra μ · nº geral 26565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar no meio, entre 2 bíbl. ser mediador; ser árbitro 3 tard. interceder 4 negociar como mediador. 〈μεσίτης〉</p></section></article>\n<article id=\"entry-dgp-26566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 987 na letra μ · nº geral 26566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 intermediário 2 árbitro; mediador 3 in­tercessor. 〈μέσος〉</p></section></article>\n<article id=\"entry-dgp-26567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσίδιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 988 na letra μ · nº geral 26567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mediador; árbitro. 〈μέσος, ἴδιος〉</p></section></article>\n<article id=\"entry-dgp-26568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσιτεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 989 na letra μ · nº geral 26568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 posição medial ou central 2 mediação; intermediação. 〈μεσίτης〉</p></section></article>\n<article id=\"entry-dgp-26569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσιτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 990 na letra μ · nº geral 26569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estar no meio 2 ser árbitro 3 negociar como mediador, ac. 〈μεσίτης〉</p></section></article>\n<article id=\"entry-dgp-26570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 991 na letra μ · nº geral 26570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quem faz intermediação; mediador; intercessor. 〈μέσος〉</p></section></article>\n<article id=\"entry-dgp-26571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοβασιλεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 992 na letra μ · nº geral 26571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interregno; regência. 〈μεσοβα­σιλεύς〉</p></section></article>\n<article id=\"entry-dgp-26572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοβασιλεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 993 na letra μ · nº geral 26572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rei interino. 〈μέσος, βασιλεύς〉</p></section></article>\n<article id=\"entry-dgp-26573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόγαια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 994 na letra μ · nº geral 26573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o interior das terras. 〈μέσος, γαῖα〉</p></section></article>\n<article id=\"entry-dgp-26574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόγαιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 995 na letra μ · nº geral 26574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">situado no meio das terras. 〈μέσος, γαῖα〉</p></section></article>\n<article id=\"entry-dgp-26575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόγεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 996 na letra μ · nº geral 26575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μεσόγαια.</p></section></article>\n<article id=\"entry-dgp-26576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόγραφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 997 na letra μ · nº geral 26576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desenhado no meio: μ. γραμμή plut. linha média</p></section></article>\n<article id=\"entry-dgp-26577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 998⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 998 na letra μ · nº geral 26577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">proporcional. 〈μέσος, γράφω〉 μεσόδμη, ης (ἡ) 1 viga principal 2 viga transversal onde se ajusta o mastro 3 espaço ou distância entre as vigas. 〈μέσος, δέμω〉</p></section></article>\n<article id=\"entry-dgp-26578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόκοιλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 999 na letra μ · nº geral 26578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oco no meio. 〈μέσος, κοῖλος〉</p></section></article>\n<article id=\"entry-dgp-26579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσολαβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1000 na letra μ · nº geral 26579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pegar no meio, i.e., surpreender; interceptar; interromper, ac. 〈μεσολαβής〉</p></section></article>\n<article id=\"entry-dgp-26580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσολαβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1001 na letra μ · nº geral 26580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preso pelo meio. 〈μέσος, λαμβάνω〉</p></section></article>\n<article id=\"entry-dgp-26581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόλευκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1002 na letra μ · nº geral 26581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">branco no meio; mesclado de branco. 〈μέσος, λευκός〉</p></section></article>\n<article id=\"entry-dgp-26582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσόμφαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1003 na letra μ · nº geral 26582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está no umbigo, no meio, no centro, partic. para Delfos, considerada o centro da Ter­ra 2 que tem um umbigo, um nó, um ponto no centro. 〈μέσος, ὀμφαλός〉</p></section></article>\n<article id=\"entry-dgp-26583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσονύκτιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1004 na letra μ · nº geral 26583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do meio da noite ♦ τὸ μεσονύκτιον 2 o meio da noite; meia-noite. 〈μέσος, νύξ〉</p></section></article>\n<article id=\"entry-dgp-26584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοπόλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1005 na letra μ · nº geral 26584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μεσαιπόλιος.</p></section></article>\n<article id=\"entry-dgp-26585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοπόρφυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1006 na letra μ · nº geral 26585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mesclado de púrpura. 〈μέσος, πορφύρα〉</p></section></article>\n<article id=\"entry-dgp-26586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοποτάμιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1007 na letra μ · nº geral 26586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 situado entre dois rios 2 situado no meio de um rio ♦ ἡ Μεσοποταμία 3 Mesopotâmia, região entre o Tigre e o Eufrates. 〈μέσος, ποταμός〉</p></section></article>\n<article id=\"entry-dgp-26587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μεσοποταμίτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1008 na letra μ · nº geral 26587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) habitante ou originário da Mesopotâmia. 〈Μεσοποταμία〉</p></section></article>\n<article id=\"entry-dgp-26588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοπτερύγια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1009 na letra μ · nº geral 26588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espaço entre as duas asas. 〈μέσος, πτέρυξ〉</p></section></article>\n<article id=\"entry-dgp-26589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοπύργιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1010 na letra μ · nº geral 26589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">intervalo entre duas torres; muralha. 〈μέσος, πύργος〉</p></section></article>\n<article id=\"entry-dgp-26590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσορί</h1><div class=\"entry-meta\"><span>DGP · ordem 1011 na letra μ · nº geral 26590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) mês egípcio, correspondente ao mês de agosto, no calendário romano.</p></section></article>\n<article id=\"entry-dgp-26591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μέσος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1012 na letra μ · nº geral 26591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. μεσαίτερος; superl. μεσαίτατος, poét. μέσατος, ép. μέσσατος) 1 no centro; no meio; na metade (do corpo): πρῆσεν μέσον ἱστίον hom. inflou a parte média</p></section></article>\n<article id=\"entry-dgp-26592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1013⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1013 na letra μ · nº geral 26592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da vela, i.e., o centro da vela, ἐν μέσσῃ δὲ [σχεδίῃ] καθῖζε hom. sentou-se no meio da jangada, κατὰ μέσην τὴν νῆσον plat. no centro da ilha, τὴν Θρᾴτταν μέσσην λαβόντα ar. agarrando a trácia pelo meio do corpo, i.e., pela cintura, σ’ ἔχω μέσον λαβών ar. agarrei-te pela cintura e te seguro firme 2 que está pela metade: μέσον ἧμαρ pínd., μέση ἡμέρα herod. o meio do dia, μέσαι νύκτες her. o meio da noite, θέρευς ἔτι μέσσου ἐόντος hom. era ainda o meio do verão 3 que fica no meio entre dois extremos; intermediário; de situação mediana (social, política ou econômica); de grandeza mediana central; intermédio; mediano: νῆσος μέσσῃ ἁλί hom. ilha situada no meio do mar, ὁ μέσος κύκλος artt. o equador, μέση θράσους μὲν καὶ δειλίας ἀνδρεία fílon a coragem está a meio-caminho entre a ousadia e a covardia, μέσος πολίτης tuc. cidadão de condição média</p></section></article>\n<article id=\"entry-dgp-26593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1014⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1014 na letra μ · nº geral 26593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">, οἱ τοῦ μέσου βίου luc. gente de condição de vida mediana, classe média</p></section></article>\n<article id=\"entry-dgp-26594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1015⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1015 na letra μ · nº geral 26594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">, μέσοι ἄνθρωποι plat. homens de posses média</p></section></article>\n<article id=\"entry-dgp-26595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1016⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1016 na letra μ · nº geral 26595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">s 4 justo; imparcial; eqüidoso: μέσος δικαστής tuc. árbitro imparcial ♦ ὁ μέσος 5 o mediador 6 homem médio, mediano: μέσου ἐστὶν ἡ δικαιοσύνη artt. a justiça é própria do homem médio, οἱ μέσοι artt. homens de condição econômica mediana ♦ ἡ μέση 7 (χορδή) a nota central da harmonia, corresp. ao lá 8 na lira de sete cordas, corda do meio que produz a nota lá 9 Gram. o acento intermediário, i.e., circunflexo 10 ἡ μέση εὐθεῖα (γραμμή) a linha reta que indica a proporção; média</p></section></article>\n<article id=\"entry-dgp-26596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1017⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1017 na letra μ · nº geral 26596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">proporcional ♦ τὸ μέσον 11 o meio de um objeto; o centro: εἰς τὸ μέσον τοῦ στρατοπέδου xen. no meio do campo, τὸ μ. ἡμέρας xen. o meio do dia 12 o que está no meio, à disposição de todos; em público: γυναῖκ’ ἐς μέσσον τιθέναι hom. colocar uma mulher como preço da luta (para o vencido) no meio da assembléia, γνώμην ἐς τὸ μέσον φέρειν ou τιθέναι apresentar um parecer, emitir uma opinião em público, εἰς μέσον παριέναι aparecer em público 13 o meio; intervalo; distância entre dois ou mais objetos: διὰ μέσου plat. no intervalo, κατὰ μέσον, κατὰ μέσσον hom. no meio, κατὰ μέσον τῆς στρατιᾶς xen. no meio do exército, ἐς μέσον ἀμφοτέροισι hom. no meio de dois, κὰδ δὲ μέσον τάφρου καὶ τείχεος hom. entre o fosso e o muro 14 imparcialidade; neutralidade: ἐς μέσον ἀμφοτέροισι δικάσασθαι hom. julgar de maneira imparcial para ambos, ἐκ τοῦ μέσου κατῆσθαι ou ἔζεσθαι her. ficar imparcial ou neutro 15 termo médio; a média</p></section></article>\n<article id=\"entry-dgp-26597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1018⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1018 na letra μ · nº geral 26597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">16 a metade: ἐκ μέσου pela metade, ἔτη ὀκτὼ καὶ ἔνατον ἐκ μέσου tuc. oito anos e o nono pela metade, i.e., oito anos e meio ♦ ἐν μέσῳ 17 no meio, i.e., ao alcance prontamente 18 o que está no meio do caminho como obstáculo; impedimento: ἡ γὰρ θάλαττα ἐν τῷ μέσῳ xen. pois o mar é obstáculo, οὐδὲν ἦν μέσῳ πολεμεῖν ἡμᾶς dem. nada era obstáculo para fazermos a guerra ♦ τὰ μέσα 19 o meio: τὰ μέσα τῆς πόλεως plat. o meio da cidade ♦ μέσον, ép. μέσσον adv. 20 no meio 21 pelo meio do corpo; pela cintura: μέσον ἔχειν, λαμβά­νειν, ἁρπάζειν ar. segurar, pegar pelo meio do corpo. μεσότης, ητος (ἡ) 1 posição medial; espaço intermediário 2 o meio entre dois extremos 3 Gram. voz média</p></section></article>\n<article id=\"entry-dgp-26598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" data-source-fragment=\"true\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">⟦fragmento sem lema no XML · μ 1019⟧</h1><div class=\"entry-meta\"><span>DGP · fragmento sem lema · ordem 1019 na letra μ · nº geral 26598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">. 〈μέσος〉 μεσότοιχον, ου (τό) bíbl. 1 muro divisório 2 barreira; obstáculo. 〈μέσος, τοῖχος〉</p></section></article>\n<article id=\"entry-dgp-26599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσοτομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1020 na letra μ · nº geral 26599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cortar pelo meio; repartir em dois. 〈μεσσό­τομος〉</p></section></article>\n<article id=\"entry-dgp-26600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεσουρανέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1021 na letra μ · nº geral 26600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estar no meio do céu, i.e., no zênite ou ao sul. 〈μέσος, οὐρανός〉</p></section></article>\n";
